#[test]
fn enemy_offset_and_shared_creator_both_use_secondary_height_only_when_needed() {
    for (primary, secondary_calls, expected_z) in [(None, 2, 33.0), (Some(4.0), 0, 4.0)] {
        let mut scene = Scene::default();
        scene.terrain.height = primary;
        scene.terrain.secondary = Some(33.0);
        let mut rng = NativeRng::from_words([0; 4]);
        ChestSystem::default().enemy_death(
            &RunClock::default(),
            &EnemyDefinition {
                id: 609,
                chest_flag: 1,
                ..Default::default()
            },
            Position::new(10.0, 20.0, -9.0),
            &mut scene.field(&mut rng, &ZONE, Position::default()),
        );
        assert_eq!(
            scene.pickups[0].position,
            Position::new(12.0, 19.0, expected_z)
        );
        assert_eq!(scene.terrain.calls, 2);
        assert_eq!(scene.terrain.secondary_calls, secondary_calls);
    }
}

